using System.IO.Compression;
using System.Reflection;
using System.Text;
using System.Text.Json;
using ZeldaCompanion;

static class MusicDiagnostics
{
    static readonly List<string> checks=[];
    static bool snapshots=true;
    static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
    static T Field<T>(object form,string name)=>(T)form.GetType().GetField(name,Flags)!.GetValue(form)!;
    static void Check(bool condition,string text){if(!condition)throw new Exception("FAILED "+text);checks.Add(text);Console.WriteLine("PASS "+text);}
    static byte[] Pcm(uint loop=0){using var s=new MemoryStream();using var w=new BinaryWriter(s);w.Write("MSU1"u8);w.Write(loop);for(int n=0;n<400;n++)w.Write((short)(n%2==0?1200:-1200));return s.ToArray();}
    static void Zip(string file,params (string name,byte[] bytes)[] contents){using var zip=ZipFile.Open(file,ZipArchiveMode.Create);foreach(var c in contents){using var s=zip.CreateEntry(c.name).Open();s.Write(c.bytes);}}
    static async Task Reject(Func<Task> action,string reason){bool refused=false;try{await action();}catch(InvalidDataException){refused=true;}Check(refused,reason);}
    static void Pump(int ms){var timer=System.Diagnostics.Stopwatch.StartNew();while(timer.ElapsedMilliseconds<ms){Application.DoEvents();Thread.Sleep(15);}}
    static void Capture(Form form,string name,string folder,string helper){if(!snapshots)return;Pump(150);var p=new System.Diagnostics.ProcessStartInfo("python"){UseShellExecute=false,CreateNoWindow=true};p.ArgumentList.Add(helper);p.ArgumentList.Add(form.Handle.ToInt64().ToString());p.ArgumentList.Add(Path.Combine(folder,name+".png"));using var process=System.Diagnostics.Process.Start(p)!;process.WaitForExit();Check(process.ExitCode==0,"captured actual window: "+name);}
    public static int ImportPersonal(string archive,string data,string ini,string title,string source){try{var lib=new SoundtrackLibrary(data);var p=lib.ImportZip(archive,Console.WriteLine,default,title,source).GetAwaiter().GetResult();lib.Save(new(p.Id,70,true,false),ini);Console.WriteLine(JsonSerializer.Serialize(p));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
    public static int Run(string folder,string helper,string archive,bool capture=true){snapshots=capture;try{
        Directory.CreateDirectory(folder);string scratch=Path.Combine(Install.Root,"music-fixtures-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(scratch);var lib=new SoundtrackLibrary(Path.Combine(scratch,"UserData"));string ini=Path.Combine(scratch,"Game","zelda3.ini");Directory.CreateDirectory(Path.GetDirectoryName(ini)!);File.Copy(Path.Combine(Install.Game,"zelda3.ini"),ini);byte[] old=File.ReadAllBytes(ini);
        Check(!lib.Managed&&lib.Packs().Length==0,"new installation starts with original music and an empty library");string small=Path.Combine(scratch,"valid.zip");Zip(small,("audio/zelda-1.pcm",Pcm()),("audio/zelda-2.pcm",Pcm(5)),("audio/zelda.sfc",new byte[32]),("audio/zelda.msu",new byte[20]));var pack=lib.ImportZip(small,_=>{}).GetAwaiter().GetResult();
        Check(pack.Tracks.SequenceEqual(new[]{1,2})&&Directory.GetFiles(Path.Combine(lib.Folder,pack.Id)).Length==3,"ZIP import copies only validated numbered audio and its manifest");
        Check(pack.Sha256.Count==2&&pack.Bytes==2*Pcm().Length,"track hashes and installed byte count are recorded");var duplicate=lib.ImportZip(small,_=>{}).GetAwaiter().GetResult();Check(pack.Id==duplicate.Id&&lib.Packs().Length==1,"identical soundtrack imports do not create duplicate packs");
        File.Delete(Path.Combine(lib.Folder,pack.Id,"track-2.pcm"));var repaired=lib.ImportZip(small,_=>{}).GetAwaiter().GetResult();Check(File.Exists(Path.Combine(lib.Folder,repaired.Id,"track-2.pcm"))&&Directory.GetDirectories(lib.Folder).Any(p=>Path.GetFileName(p).StartsWith(".previous-")),"reimport repairs missing audio and retains the previous pack as a backup");
        lib.Save(new(pack.Id,65,true,false),ini);Check(File.ReadAllBytes(Directory.GetFiles(Path.Combine(scratch,"UserData","SettingsBackups")).Single()).SequenceEqual(old),"music settings create an exact backup before writing");Check(lib.Choice()==new SoundtrackChoice(pack.Id,65,true,false),"saved music choice reloads");string text=File.ReadAllText(ini);Check(text.Contains("EnableMSU = true")&&text.Contains("AudioFreq = 44100")&&text.Contains("AudioChannels = 2")&&text.Contains("MSUVolume = 65%"),"PCM mode selects the required stereo sample rate and music volume");Check(text.Contains("Fullscreen = 1")&&text.Contains("Controls = Up, Down, Left, Right"),"soundtrack changes retain graphics and key bindings");
        string online=Path.Combine(scratch,"UserData","Online","test-room");Directory.CreateDirectory(online);File.Copy(ini,Path.Combine(online,"zelda3.ini"));lib.PrepareForLaunch(online,_=>{});string prefix=Read(Path.Combine(online,"zelda3.ini"),"MSUPath");Check(File.Exists(Path.GetFullPath(Path.Combine(online,prefix+"1.pcm"))),"online campaign resolves the same personal soundtrack through a relative path");
        string moved=scratch+"-moved";if(!Path.GetFullPath(scratch).StartsWith(Path.GetFullPath(Install.Root),StringComparison.OrdinalIgnoreCase)||!Path.GetFullPath(moved).StartsWith(Path.GetFullPath(Install.Root),StringComparison.OrdinalIgnoreCase))throw new IOException("Test relocation is outside the private build folder.");Directory.Move(scratch,moved);scratch=moved;lib=new(Path.Combine(moved,"UserData"));ini=Path.Combine(moved,"Game","zelda3.ini");lib.PrepareForLaunch(Path.GetDirectoryName(ini)!,_=>{});prefix=Read(ini,"MSUPath");Check(File.Exists(Path.GetFullPath(Path.Combine(Path.GetDirectoryName(ini)!,prefix+"1.pcm"))),"soundtrack still resolves after moving the portable installation");
        lib.Save(new("",65,true,false),ini);Check(Read(ini,"EnableMSU")=="false"&&Directory.Exists(Path.Combine(lib.Folder,pack.Id)),"original music can be restored without deleting the imported pack");
        byte[] transaction=File.ReadAllBytes(ini);bool rollback=false;using(var locked=new FileStream(Path.Combine(scratch,"UserData","soundtrack-settings.json"),FileMode.Open,FileAccess.Read,FileShare.None)){try{lib.Save(new(pack.Id,50,true,false),ini);}catch(Exception e)when(e is IOException or UnauthorizedAccessException){rollback=true;}}Check(rollback&&File.ReadAllBytes(ini).SequenceEqual(transaction)&&lib.Choice().PackId=="","failed choice-file commit restores the game settings and keeps the saved choice");
        int unchanged=lib.Packs().Length;string bad=Path.Combine(scratch,"bad.zip");Zip(bad,("../outside-1.pcm",Pcm()));Reject(()=>lib.ImportZip(bad,_=>{}),"unsafe ZIP paths are rejected").GetAwaiter().GetResult();
        bad=Path.Combine(scratch,"bad-header.zip");Zip(bad,("music-1.pcm",new byte[50]));Reject(()=>lib.ImportZip(bad,_=>{}),"invalid audio magic is rejected").GetAwaiter().GetResult();
        bad=Path.Combine(scratch,"bad-loop.zip");Zip(bad,("music-1.pcm",Pcm(10000)));Reject(()=>lib.ImportZip(bad,_=>{}),"loop points beyond the audio are rejected").GetAwaiter().GetResult();
        bad=Path.Combine(scratch,"mixed.zip");Zip(bad,("first/a-1.pcm",Pcm()),("second/a-1.pcm",Pcm()));Reject(()=>lib.ImportZip(bad,_=>{}),"multiple track sets are rejected with folder-import guidance").GetAwaiter().GetResult();
        bad=Path.Combine(scratch,"duplicate.zip");Zip(bad,("a-1.pcm",Pcm()),("a-01.pcm",Pcm()));Reject(()=>lib.ImportZip(bad,_=>{}),"duplicate numeric track IDs are rejected").GetAwaiter().GetResult();
        Check(lib.Packs().Length==unchanged&&!Directory.GetDirectories(lib.Folder).Any(p=>Path.GetFileName(p).StartsWith(".import-")),"failed imports leave existing packs intact and clean their own staging folders");
        string sourceFolder=Path.Combine(scratch,"folder-pack");Directory.CreateDirectory(sourceFolder);File.WriteAllBytes(Path.Combine(sourceFolder,"new-4.pcm"),Pcm());var folderPack=lib.ImportFolder(sourceFolder,_=>{}).GetAwaiter().GetResult();Check(folderPack.Tracks.SequenceEqual(new[]{4}),"extracted-folder import works");
        using(var cancel=new CancellationTokenSource()){cancel.Cancel();bool stopped=false;try{lib.ImportFolder(sourceFolder,_=>{},cancel.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){stopped=true;}Check(stopped,"cancelled import is stopped before installation");}
        var opuz=new byte[30];Encoding.ASCII.GetBytes("OPUZ").CopyTo(opuz,0);string opusFolder=Path.Combine(scratch,"opuz-pack");Directory.CreateDirectory(opusFolder);File.WriteAllBytes(Path.Combine(opusFolder,"audio-1.opuz"),opuz);Reject(()=>lib.ImportFolder(opusFolder,_=>{}),"invalid OPUZ ranges are rejected before installation").GetAwaiter().GetResult();BitConverter.GetBytes(18u).CopyTo(opuz,8);BitConverter.GetBytes(960u).CopyTo(opuz,12);BitConverter.GetBytes((ushort)0x8000).CopyTo(opuz,16);File.WriteAllBytes(Path.Combine(opusFolder,"audio-1.opuz"),opuz);var opus=lib.ImportFolder(opusFolder,_=>{}).GetAwaiter().GetResult();lib.Save(new(opus.Id,80,false,true),ini);Check(Read(ini,"EnableMSU")=="deluxe-opuz"&&Read(ini,"AudioFreq")=="48000"&&Read(ini,"ResumeMSU")=="0","OPUZ/Deluxe selection configures the native mode and sample rate (range fixture only)");
        byte[] preserve=File.ReadAllBytes(Path.Combine(Install.Game,"zelda3.ini"));string hash=Install.GameplayHash();try{File.Copy(ini,Path.Combine(Install.Game,"zelda3.ini"),true);Check(hash==Install.GameplayHash(),"personal soundtrack options do not change online compatibility");}finally{File.WriteAllBytes(Path.Combine(Install.Game,"zelda3.ini"),preserve);}
        using(var form=new MainForm()){form.Show();typeof(MainForm).GetMethod("ShowPage",Flags)!.Invoke(form,["music"]);Capture(form,"music-empty",folder,helper);var page=Field<object>(form,"music");Check(!Field<NumericUpDown>(page,"volume").Enabled,"original music disables irrelevant MSU volume controls");form.Close();}
        var real=new SoundtrackLibrary(Install.Data);var orchestral=Task.Run(()=>real.ImportZip(archive,_=>{},default,"A Link to the Past Orchestral — JUD6MENT (2023)","https://www.zeldix.net/t791-the-legend-of-zelda-a-link-to-the-past")).GetAwaiter().GetResult();Check(orchestral.Tracks.Length==35&&SoundtrackLibrary.MissingStandard(orchestral).Length==0,"real creator-listed orchestral pack validates all 35 PCM files and standard coverage");real.Save(new(orchestral.Id,70,true,false),Path.Combine(Install.Game,"zelda3.ini"));
        using(var form=new MainForm()){form.Show();typeof(MainForm).GetMethod("ShowPage",Flags)!.Invoke(form,["music"]);Capture(form,"music-installed",folder,helper);var page=Field<object>(form,"music");Check(Field<NumericUpDown>(page,"volume").Enabled,"installed soundtrack enables its music options");Field<NumericUpDown>(page,"volume").Value=66;Field<Button>(page,"save").PerformClick();Pump(200);Check(real.Choice().Volume==66,"actual Use this soundtrack button saves the edited volume");form.ClientSize=new System.Drawing.Size(924,681);Capture(form,"music-small",folder,helper);form.Close();}
        File.WriteAllText(Path.Combine(folder,"music-results.json"),JsonSerializer.Serialize(new{checks,pack=orchestral,nativeAudioPlaybackTested=false},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(checks.Count+" music assertions passed.");return 0;
    }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
    static string Read(string ini,string key){foreach(string line in File.ReadLines(ini)){int eq=line.IndexOf('=');if(eq>0&&line[..eq].Trim()==key)return line[(eq+1)..].Trim();}return "";}
}
